import{_ as r,o as l,c as t,a2 as o}from"./chunks/framework.mRCPFc5l.js";const c=JSON.parse('{"title":"艾莉芙（副院长）","description":"","frontmatter":{},"headers":[],"relativePath":"表层/人物/艾莉芙.md","filePath":"表层/人物/艾莉芙.md","lastUpdated":null}'),e={name:"表层/人物/艾莉芙.md"};function i(n,a,s,h,d,u){return l(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="艾莉芙-副院长" tabindex="-1">艾莉芙（副院长） <a class="header-anchor" href="#艾莉芙-副院长" aria-label="Permalink to &quot;艾莉芙（副院长）&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><ul><li><strong>名称</strong>：艾莉芙</li><li><strong>种族</strong>：精灵族</li><li><strong>身份</strong>：红星孤儿院副院长</li><li><strong>时代</strong>：当前时代（共同体覆灭后至今）</li><li><strong>所在地</strong>：红星孤儿院</li><li><strong>状态</strong>：隐居状态，直属并完全听命于孤儿院院长维斯塔</li></ul><h2 id="外貌特征" tabindex="-1">外貌特征 <a class="header-anchor" href="#外貌特征" aria-label="Permalink to &quot;外貌特征&quot;">​</a></h2><h3 id="精灵族特征" tabindex="-1">精灵族特征 <a class="header-anchor" href="#精灵族特征" aria-label="Permalink to &quot;精灵族特征&quot;">​</a></h3><p>作为世界观中唯一长得像人的种族，艾莉芙具有精灵族的典型特征：</p><ul><li><strong>尖耳</strong>：明显的精灵族尖耳特征</li><li><strong>发色</strong>：白色长发</li><li><strong>瞳色</strong>：金色</li><li><strong>服饰</strong>：一身简洁的白袍，有金色条纹作装饰，符合精灵族传统</li><li><strong>法杖</strong>：手持一&quot;木制法杖&quot;，外观古朴</li></ul><h3 id="气质特点" tabindex="-1">气质特点 <a class="header-anchor" href="#气质特点" aria-label="Permalink to &quot;气质特点&quot;">​</a></h3><ul><li><strong>生人勿近</strong>：性格偏冷，默认对外人保持一定的社交距离</li><li><strong>对孩包容</strong>：对孤儿院的孩子们展现出温和、包容的一面，是孩子们信赖的长辈</li><li><strong>从容镇定</strong>：行为从容不迫，处事不惊，有着精灵族特有的沉稳</li><li><strong>观察敏锐</strong>：眼神敏锐，善于观察，但不轻易表露自己的想法</li></ul><h2 id="副院长定位与职责" tabindex="-1">副院长定位与职责 <a class="header-anchor" href="#副院长定位与职责" aria-label="Permalink to &quot;副院长定位与职责&quot;">​</a></h2><h3 id="孤儿院规模与人员结构" tabindex="-1">孤儿院规模与人员结构 <a class="header-anchor" href="#孤儿院规模与人员结构" aria-label="Permalink to &quot;孤儿院规模与人员结构&quot;">​</a></h3><p>红星孤儿院并非大型机构，工作人员很少，整个孤儿院的人员制度实际上更倾向于<strong>院长最高，其余工作人员平级</strong>的结构。</p><h3 id="副院长-名头的实际含义" tabindex="-1">&quot;副院长&quot;名头的实际含义 <a class="header-anchor" href="#副院长-名头的实际含义" aria-label="Permalink to &quot;&quot;副院长&quot;名头的实际含义&quot;">​</a></h3><p>&quot;副院长&quot;这一名头并非严格的层级职务，而是基于艾莉芙的实际职责：</p><ol><li><strong>职责核心</strong>：负责将院长的安排落实，管理孤儿院日常维护</li><li><strong>协调角色</strong>：负责各个其余工作人员的对接与协调</li><li><strong>指令传递</strong>：帮忙传递院长安排指令，确保信息畅通</li><li><strong>对外接口</strong>：负责与外界的一些必要对接，代表孤儿院处理外部事务</li></ol><h2 id="历史背景" tabindex="-1">历史背景 <a class="header-anchor" href="#历史背景" aria-label="Permalink to &quot;历史背景&quot;">​</a></h2><h3 id="精灵族大变故" tabindex="-1">精灵族大变故 <a class="header-anchor" href="#精灵族大变故" aria-label="Permalink to &quot;精灵族大变故&quot;">​</a></h3><p>精灵族经历了一次鲜为人知的大变故。变故之后，大多数精灵选择隐居，不再参与时事，变故的具体原因至今没有明确记载，是大陆上的一个谜团。</p><h3 id="隐居与副院长任职" tabindex="-1">隐居与副院长任职 <a class="header-anchor" href="#隐居与副院长任职" aria-label="Permalink to &quot;隐居与副院长任职&quot;">​</a></h3><blockquote><p>待定：艾莉芙如何在精灵族大变故后进入红星孤儿院并担任副院长，尚无明确记载。已知她完全听命于院长维斯塔，对其无比信任。</p></blockquote><h2 id="与维斯塔的关系" tabindex="-1">与维斯塔的关系 <a class="header-anchor" href="#与维斯塔的关系" aria-label="Permalink to &quot;与维斯塔的关系&quot;">​</a></h2><h3 id="对院长的认知" tabindex="-1">对院长的认知 <a class="header-anchor" href="#对院长的认知" aria-label="Permalink to &quot;对院长的认知&quot;">​</a></h3><ul><li><strong>身份感知</strong>：艾莉芙隐约能知道院长的身份不一般，但并不知道院长的真实身份</li><li><strong>尊重态度</strong>：基于这种感知，她对维斯塔保持着超越普通上下级的尊重</li><li><strong>无比信任</strong>：对维斯塔有着无比的信任，相信院长的所有决定和安排</li><li><strong>默契配合</strong>：与维斯塔形成了工作上的默契，能够准确理解并落实院长的意图</li></ul><h3 id="角色互补" tabindex="-1">角色互补 <a class="header-anchor" href="#角色互补" aria-label="Permalink to &quot;角色互补&quot;">​</a></h3><ul><li><strong>维斯塔的延伸</strong>：在某种程度上，艾莉芙是维斯塔在孤儿院日常管理中的延伸</li><li><strong>缓冲桥梁</strong>：作为院长与工作人员、孤儿院与外界的缓冲和桥梁</li><li><strong>可靠执行者</strong>：维斯塔可以放心地将事务交给艾莉芙执行</li></ul><hr><h2 id="真相档案" tabindex="-1">真相档案 <a class="header-anchor" href="#真相档案" aria-label="Permalink to &quot;真相档案&quot;">​</a></h2><blockquote><p>以上是表层生灵所能知晓的全部。此人的真实身份与完整档案（含大量剧透），见<a href="./../../中层/人物/艾莉芙" class="layer-link" data-layer="中层">艾莉芙（真相档案）</a>。</p></blockquote><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../种族/精灵族">精灵族</a></li><li><a href="./维斯塔">维斯塔</a></li><li><a href="./../../中层/世界/特殊地点" class="layer-link" data-layer="中层">红星孤儿院</a></li><li><a href="./">众生录</a></li></ul><hr>',31)])])}const q=r(e,[["render",i]]);export{c as __pageData,q as default};
